  }
}
wp> $wpdb->delete( $wpdb->options, array( 'option_name' => 'test-option' ) );
=> int(1)
wp> $wpdb->get_results( 'SELECT * FROM wp_options WHERE option_name="test-option"' );
=> array(0) {
}
wp> get_option( 'test-option' );
=> string(7) "example"
wp> delete_option( 'test-option' );
=> bool(false)
wp> get_option( 'test-option' );
=> string(7) "example"
